    "af66522c": {"text":"0;) { const a = FBDATA.ailments[c.ails[i]]; if (a && a.kind === kind) { c.ails.splice(i, 1); Sinistra--; } altrimenti i++; } if (!c.ails.length) cancella c.ails; }; FB.randomWound = funzione (sev) { const pool = []; for (id const in FBDATA.ailments) { const a = FBDATA.ailments[id]; if (a.kind === 'ferita' && (a.sev || 1) === sev) pool.push(id); } restituisce pool.lunghezza ? FB.pick(pool): null; }; FB.randomSickness = funzione () { const pool = []; for (const id in FBDATA.ailments) { if (FBDATA.ailments[id].kind === 'malattia') pool.push(id); } restituisce pool.lunghezza ? FB.pick(pool): null; }; FB.traitAgg = funzione (c) { const agg = { dip: 0, mar: 0, ste: 0, int: 0, lea: 0, salute: 0, fert: 1, opinione: 0 }; for (const id di c.traits) { const t = FBDATA.traits[id]; se (!t) continua; for (cost s di COMPETENZE) if (t[s]) agg[s] += t[s]; if (t.salute) agg.salute += t.salute; if (t.fert) agg.fert *= t.fert; if (t.opinione) agg.opinione += t.opinione; } restituisce agg; }; function baseAbilità(c, chiave) { if (!c) return 0; competenze costanti = c.competenze || {}; return (competenze[chiave] || 0) + (FB.traitAgg(c)[chiave] || 0); } FB.skillOf = funzione (c, chiave) { let v = baseSkill(c, chiave); // Gli attrezzi domestici equipaggiati migliorano chi lo indossa (FB.itemBonus si caricherà più tardi). if (c && FB.state && FB.itemBonus && FB.state.chars && FB.state.chars[c.id] === c) v += FB.itemBonus(FB.state, key, c.id); return Math.max(0, v); }; FB.skillSnapshot = funzione (stato, c, chiave) { let v = baseSkill(c, chiave); if (state && c && FB.itemBonusReadOnly && state.chars && state.chars[c.id] === c) { v += FB.itemBonusReadOnly(state, key, c.id); } restituisce Math.max(0, v); }; /* La crescita delle abilità non ha limiti. Sotto balance.skillSoftCap ogni guadagno arriva; oltrepassandolo ogni punto deve battere un tiro (softCap/current)^2. Al raggiungimento e al di là di balance.skillMasteryThreshold la possibilità viene ulteriormente moltiplicata per (masteryThreshold/current)^skillMasteryPower. Solo l'abilità addestrata grezza stabilisce queste probabilità; le caratteristiche e l'attrezzatura non rendono l'allenamento più difficile. Restituisce i punti effettivamente guadagnati. */ FB.gainSkill = funzione (c, chiave, n) { const B = FBDATA.balance; const soft = B.skillSoftCap || 20; const maestria = B.skillMasteryThreshold || 40; const power = B.skillMasteryPower !== non definito ? B.skillMasteryPotere: 8; lascia guadagnato = 0; per (sia i = 0; i","hash":"h1-b90ffcec"},
